function finishRace(){if(state.finished)return;state.finished=true;state.started=false;stopEngine();state.player.mode='celebration';state.player.modeTime=0;const target=state.track.length*state.track.laps;const finishers=[{name:state.playerName,progress:target,time:state.raceTime,player:true},...state.rivals.map(r=>({name:r.name,progress:r.position,time:r.finishTime,player:false}))].sort((a,b)=>{if(a.time!==null&&b.time!==null)return a.time-b.time;if(a.time!==null)return-1;if(b.time!==null)return 1;return b.progress-a.progress});const pos=finishers.findIndex(r=>r.player)+1;state.position=pos;const points=[6800,5400,4500,3700,3000,2500][pos-1],timeBonus=Math.max(0,Math.round(2800-state.raceTime*20)),score=Math.max(600,Math.round(points+timeBonus+state.pickups*180-state.hits*120+state.track.difficulty*550));state.raceScore=score;publishScore(score,{event:'race-complete',track:state.track.name,trackIndex:state.trackIndex+1,position:pos,timeSeconds:Number(state.raceTime.toFixed(2)),pickups:state.pickups,hits:state.hits,animationSystem:'grid-powers-ai-v7'});state.completed[state.trackIndex]=true;if(state.trackIndex<2)state.unlocked=Math.max(state.unlocked,state.trackIndex+1);saveProgress();announce(pos===1?'¡VICTORIA CIFRADA!':'META ALCANZADA','PROTOCOLO COMPLETADO',1800);tone(pos<=3?760:360,.55,'sawtooth');setTimeout(()=>showResults(finishers,pos,score),2200)}
