$('#startRaceBtn').addEventListener('click',setupRace);$('#useItemBtn').addEventListener('click',useItem);$('#touchUsePower').addEventListener('click',useItem);$('#fireWeaponBtn').addEventListener('click',fireWeapon);$('#touchFireWeapon').addEventListener('click',fireWeapon);$('#pauseBtn').addEventListener('click',()=>togglePause());$('#resumeBtn').addEventListener('click',()=>togglePause(false));$('#quitBtn').addEventListener('click',()=>{togglePause(false);stopEngine();renderGarage();showScreen('garage')});$('#retryBtn').addEventListener('click',setupRace);$('#continueBtn').addEventListener('click',()=>{if(state.trackIndex<2)state.trackIndex=Math.min(state.trackIndex+1,state.unlocked);renderGarage();showScreen('garage')});$('#printBtn').addEventListener('click',()=>window.print());$('#soundBtn').addEventListener('click',()=>{state.audio=!state.audio;$('#soundBtn').textContent=state.audio?'🔊':'🔇';if(!state.audio)stopEngine();else if(state.started&&!state.paused)startEngine()});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','ShiftLeft','ShiftRight','KeyQ','KeyE'].includes(e.code))e.preventDefault();state.keys[e.code]=true;if(e.code==='Space'||e.code==='KeyQ')useItem();if(e.code==='KeyE')fireWeapon();if(e.code==='Escape')togglePause();syncControlVisuals()});window.addEventListener('keyup',e=>{state.keys[e.code]=false;syncControlVisuals()});window.addEventListener('blur',()=>{state.mouse.active=false;state.mouse.drift=false;Object.keys(state.keys).forEach(k=>state.keys[k]=false);syncControlVisuals();if(state.screen==='race'&&state.started)togglePause(true)});window.addEventListener('resize',resize);document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.screen==='race'&&state.started)togglePause(true)});
$$('[data-control]').forEach(btn=>{const key=btn.dataset.control;const down=e=>{e.preventDefault();state.keys[key]=true;btn.classList.add('pressed');btn.setAttribute('aria-pressed','true');btn.setPointerCapture?.(e.pointerId);syncControlVisuals()};const up=e=>{e.preventDefault();state.keys[key]=false;btn.classList.remove('pressed');btn.setAttribute('aria-pressed','false');syncControlVisuals()};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up);btn.addEventListener('contextmenu',e=>e.preventDefault())});
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;state.mouse.steer=clamp((e.clientX/innerWidth-.5)*2,-1,1);if(e.button===2)state.mouse.drift=true;else if(e.button===0)state.mouse.active=true;canvas.setPointerCapture?.(e.pointerId);syncControlVisuals()});canvas.addEventListener('pointermove',e=>{if(state.mouse.active||state.mouse.drift)state.mouse.steer=clamp((e.clientX/innerWidth-.5)*2,-1,1)});canvas.addEventListener('pointerup',e=>{if(e.button===2)state.mouse.drift=false;if(e.button===0)state.mouse.active=false;syncControlVisuals()});canvas.addEventListener('pointercancel',()=>{state.mouse.active=false;state.mouse.drift=false;syncControlVisuals()});canvas.addEventListener('contextmenu',e=>e.preventDefault());
